def _parse(self, timestr, dayfirst=None, yearfirst=None, fuzzy=False, fuzzy_with_tokens=False):
    """
    Private parsing function to be called from ``parse()``.
    """
    if fuzzy_with_tokens:
        fuzzy = True

    timestr = timestr.strip()

    if not timestr:
        raise ValueError("String does not start with a date")

    res = self._result()
    skipped_tokens = []
    tokens = self._split(timestr)
    for i, token in enumerate(tokens):
        lowered = token.lower()

        if self.jump(lowered):
            continue

        for fn in (self._parse_isodate, self._parse_isotime):
            try:
                ret = fn(token)
                if ret:
                    for key, val in ret.items():
                        if key == 'hour' and val == 24:
                            # Handle ISO 24:00 (midnight) notation
                            if i + 1 < len(tokens):
                                # If there are more tokens, 24:00 represents end of day
                                res['hour'] = 0
                                res['day'] = res.get('day', 1) + 1
                            else:
                                # At end of string, 24:00 is midnight (start of next day)
                                res['hour'] = 0
                                res['day'] = res.get('day', 1) + 1
                        else:
                            res[key] = val
                    break
            except ValueError:
                continue
        else:
            try:
                ret = self._parse_isodate(token)
                if ret:
                    for key, val in ret.items():
                        res[key] = val
                    continue
            except ValueError:
                pass

            try:
                ret = self._parse_isotime(token)
                if ret:
                    for key, val in ret.items():
                        if key == 'hour' and val == 24:
                            res['hour'] = 0
                            res['day'] = res.get('day', 1) + 1
                        else:
                            res[key] = val
                    continue
            except ValueError:
                pass

            try:
                ret = self._parse_hms(token)
                if ret:
                    for key, val in ret.items():
                        res[key] = val
                    continue
            except ValueError:
                pass

            try:
                ret = self._parse_tz(token)
                if ret:
                    res['tzstr'] = token
                    continue
            except ValueError:
                pass

            try:
                ret = self._parse_relative(token)
                if ret:
                    for key, val in ret.items():
                        res[key] = val
                    continue
            except ValueError:
                pass

            if fuzzy:
                skipped_tokens.append(token)
                continue

            raise ValueError("Unknown string format: %s" % timestr)

    if fuzzy_with_tokens:
        return res, tuple(skipped_tokens)

    return self._build_tzinfo(res, fuzzy)

