def _parse_isotime(self, timestr):
    """
    Parse an ISO time string.

    Supports HH:MM:SS, HH:MM, and HH formats.
    Also supports 24:00:00 as ISO 8601 notation for midnight.
    """
    len_str = len(timestr)
    time_part = timestr

    for i, c in enumerate(timestr):
        if c not in '0123456789:.,+-Z':
            time_part = timestr[:i]
            break

    if not time_part:
        raise ValueError("Not an ISO time")

    h = m = s = ns = 0
    frac = 0
    frac_len = 0

    parts = time_part.split(':')
    if len(parts) < 1 or len(parts) > 3:
        raise ValueError("Not an ISO time")

    try:
        h = int(parts[0])
    except ValueError:
        raise ValueError("Not an ISO time")

    if h > 24:
        raise ValueError("Hour must be in 0..24")

    if len(parts) > 1:
        try:
            m = int(parts[1])
        except ValueError:
            raise ValueError("Not an ISO time")

        if m > 59:
            raise ValueError("Minute must be in 0..59")

    if len(parts) > 2:
        try:
            s_parts = parts[2].split('.')
            s = int(s_parts[0])
            if len(s_parts) > 1:
                frac_str = s_parts[1].rstrip('Z')
                frac_len = len(frac_str)
                frac = int(frac_str.ljust(6, '0')[:6])
        except ValueError:
            raise ValueError("Not an ISO time")

        if s > 59:
            raise ValueError("Second must be in 0..59")

    if h == 24 and (m != 0 or s != 0 or frac != 0):
        raise ValueError("24:00:00 is only valid at midnight")

    return {
        'hour': h,
        'minute': m,
        'second': s,
        'microsecond': frac
    }

