def _parse_hms(self, hms_tuple):
    h, m, s = hms_tuple

    if h == 24:
        if m != 0 or s != 0:
            raise ValueError("Hour 24 is only valid with 00:00")
        h = 0
        return (h, m, s, True)

    return (h, m, s, False)

