        raise ValueError(f"Unrecognized ISO 8601 date format: {dtstart!r}")

    date_part = self._parse_isodate_str(dt_str)

    if tstr is not None:
        time_comps = self._parse_isotime_str(tstr)

        if time_comps[0] == 24:
            if any(x != 0 for x in time_comps[1:4]):
                raise ValueError(f"Hour 24:00 can only be followed by 00:00")
            date_part = date_part + timedelta(days=1)
            time_comps[0] = 0

